import {mountReminderPanel} from './focus-actions.mjs';
import {emailStatus,mountSupportPolish} from './support-polish.mjs';
import {mountInbox,mountTimeline} from './communication-desk.mjs';
import {esc,conversation,request} from './customer-shared.mjs';
import {refreshFlightRecorder} from './case-intelligence.mjs';
import {customerProgressDraft} from './customer-update-draft.mjs';
export function updatePromiseState(current,notifications=[],now=Date.now()){
 const due=current?Date.parse(current):NaN;
 const timing=Number.isFinite(due)?due<=now?'overdue':'scheduled':'unset';
 const latest=notifications.at(-1);
 return {timing,email:latest?emailStatus(latest.state)[0]:'No email attempt recorded',emailAt:latest?.at||null};
}
function mountUpdatePromise(root,panel,caseId,current,notifications=[]){
 root.querySelector('.customer-update-form')?.remove();
 const form=document.createElement('form');form.className='customer-update-form';
 form.innerHTML=`<span class="eyebrow">CUSTOMER UPDATE PROMISE</span><h3>When will ${esc(root.querySelector('.case-customer strong')?.textContent||'the customer')} hear next?</h3><p>Owner: merchant · The time is visible in the private customer case. When due, PayTrace reminds your team and queues an email attempt if a verified purchase email and delivery provider are configured. You still write the progress update.</p><div class="promise-status" role="status"></div><label for="customer-update-time">Next progress update</label><input id="customer-update-time" type="datetime-local" required><div class="support-actions"><button class="button primary" type="submit">Save update time</button><button class="button" type="button" data-clear-update>Clear time</button><button class="button" type="button" data-open-conversation>Open conversation</button></div><p class="promise-feedback" role="status"></p>`;
 const communication=root.querySelector('.case-communication-area');if(communication){const thread=communication.querySelector('.case-conversation-disclosure');if(thread)thread.before(form);else communication.append(form);}else panel.prepend(form);const input=form.querySelector('input'),status=form.querySelector('.promise-status'),feedback=form.querySelector('.promise-feedback');
 function display(value){const state=updatePromiseState(value,notifications);form.classList.toggle('promise-overdue',state.timing==='overdue');status.innerHTML=state.timing==='overdue'?`<strong>Update overdue</strong><span>The customer is waiting for the progress update promised for ${esc(new Date(value).toLocaleString())}.</span>`:state.timing==='scheduled'?`<strong>Next update: ${esc(new Date(value).toLocaleString())}</strong><span>Visible in the private customer page. A merchant reminder and eligible email attempt are queued when due.</span>`:'<strong>No update time set</strong><span>Choose when the customer can expect to hear from your team.</span>';const email=document.createElement('small');email.textContent=`Latest email notification: ${state.email}${state.emailAt?' · '+new Date(state.emailAt).toLocaleString():''}. This does not confirm inbox delivery.`;status.append(email);}
 if(current&&Number.isFinite(Date.parse(current)))input.value=new Date(Date.parse(current)-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);display(current);
 async function save(dueAt){form.querySelectorAll('button').forEach(b=>b.disabled=true);feedback.textContent='Saving update time…';try{const result=await request('/api/support/update-promise',{caseId,dueAt});display(result.nextUpdateAt);feedback.textContent=result.nextUpdateAt?'Saved to the customer page. A due-time reminder is scheduled; open the conversation to post a real update.':'Update time cleared from the customer page.';if(!result.nextUpdateAt)input.value='';}catch(e){feedback.textContent=e.message;}finally{form.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 form.onsubmit=e=>{e.preventDefault();const date=new Date(input.value);if(!Number.isFinite(date.valueOf())){feedback.textContent='Choose a valid time.';return;}save(date.toISOString());};
 form.querySelector('[data-clear-update]').onclick=()=>save(null);
 form.querySelector('[data-open-conversation]').onclick=()=>{const disclosure=root.querySelector('.case-conversation-disclosure');if(disclosure){disclosure.open=true;disclosure.scrollIntoView({behavior:'smooth',block:'start'});disclosure.querySelector('#support-text')?.focus({preventScroll:true});}};
}
export function mountSupport(root,s,{backend,onSelect}){
 if(!s){if(backend)mountInbox(root,onSelect);return;}const target=root.querySelector('.case-communication-area');if(!target)return;
 const disclosure=document.createElement('details');disclosure.className='case-conversation-disclosure';disclosure.id='case-conversation';const heading=document.createElement('summary');heading.innerHTML='<span><span class="eyebrow">CUSTOMER COMMUNICATION</span><strong>Customer conversation</strong><small>Messages, questions, and notification activity</small></span><span aria-hidden="true">+</span>';disclosure.append(heading);const panel=document.createElement('section');panel.className='support-panel';disclosure.append(panel);target.append(disclosure);
 if(!backend){mountTimeline(root,s,null);panel.innerHTML='<h2>Customer communication</h2><p>Messaging and private customer links require the server-backed app.</p>';return;}
 let pending=null,busy=false;
 async function api(body){return request('/api/support'+(body?'':'?caseId='+encodeURIComponent(s.id)),body?{...body,caseId:s.id}:undefined);}
 function show(d){mountTimeline(root,s,d);refreshFlightRecorder(root,s,d);const attention=!!d.help;if(attention)disclosure.open=true;heading.querySelector('strong').textContent=attention?'Customer needs a response':d.request?'Waiting for customer':'Customer conversation';heading.querySelector('small').textContent=attention?'Open now · customer needs attention':d.request?'Information requested · waiting for the customer':`${d.messages.length} recorded messages · open to reply or inspect email status`;panel.innerHTML=`<span class="eyebrow">CUSTOMER COMMUNICATION</span><h2>Keep ${esc(s.customerName)} in the loop.</h2><p class="subtle">Customer-visible replies stay separate from the investigation. Only an unlocked operator can send messages or share access. <a href="focus.html?screen=connections">Review connection setup ↗</a></p>${d.help?'<div class="support-attention">Customer needs more help. Technical verification alone has not resolved their concern.</div>':''}${d.request?`<div class="support-attention"><strong>Waiting for the customer</strong><p>${esc(d.request)}</p></div>`:''}<p class="subtle">Customer confirmation: ${d.confirmedAt&&d.verified?'Received':'Not yet received'}</p><div class="customer-thread">${conversation(d.messages)}</div><form id="support-reply"><label for="support-kind">Message visibility</label><select id="support-kind"><option value="message">Reply to customer · human</option><option value="request">Request information · customer action needed</option><option value="internal">Private admin note · hidden from customer</option><option value="ai-draft">AI-assisted reply · reviewed by merchant</option></select><label for="support-text">Your message</label><textarea id="support-text" required maxlength="2000" placeholder="Explain the next step, or ask a specific question.">${esc(pending?.text||'')}</textarea><small>Never request passwords or full payment details. AI-assisted replies must be reviewed before sending.</small><div class="support-actions"><button class="button primary" type="submit">Save message</button><button class="button" type="button" id="support-refresh">Refresh conversation</button></div></form><details><summary>Customer link & email updates</summary><p>Register an email only after matching it to the purchase. Anyone with a private link can read this case and reply.</p><form id="support-contact"><label for="support-email">Verified purchase email</label><input id="support-email" type="email" required maxlength="254" value="${esc(d.email)}"><label class="support-check"><input type="checkbox" required> I matched this email to the purchase record.</label><button class="button" type="submit">Save purchase email</button></form><div class="support-actions"><button class="button" id="support-invite">Email private link</button><button class="button" id="support-link">Create private preview link</button><button class="button" id="support-revoke">Revoke customer links</button></div><div id="support-link-result"></div><p class="subtle">Links expire in 24 hours and can be opened once. Revoking also ends existing customer sessions.</p><h3>Email activity</h3><p class="subtle">Provider acceptance does not confirm inbox delivery. Unconfigured or failed emails are not automatically retried; send a fresh invitation after fixing setup.</p><ul>${d.notifications.slice(-5).map(n=>`<li>${esc(emailStatus(n.state)[0])} · ${esc(new Date(n.at).toLocaleString())}</li>`).join('')||'<li>No email attempts yet.</li>'}</ul></details><p class="support-feedback" role="status"></p>`;
 const feedback=()=>panel.querySelector('.support-feedback');
 const factDraft=customerProgressDraft(s,d);
 const draftPanel=document.createElement('div');draftPanel.className='case-fact-draft';
 const draftTitle=document.createElement('div');draftTitle.innerHTML='<span class="eyebrow">GROUNDED UPDATE</span><strong>Tell the buyer what we know.</strong><small>Prepared from current case facts. Review and edit before sending.</small>';
 const draftBasis=document.createElement('p');draftBasis.textContent='Based on: '+factDraft.basis.join(' · ');
 const draftButton=document.createElement('button');draftButton.type='button';draftButton.className='button';draftButton.textContent='Use case-fact draft';
 draftPanel.append(draftTitle,draftBasis,draftButton);panel.querySelector('#support-reply').before(draftPanel);
 draftButton.onclick=()=>{if(pending){feedback().textContent='Finish or refresh the pending message before starting another draft.';return;}const textarea=panel.querySelector('#support-text'),kind=panel.querySelector('#support-kind');kind.value='message';kind.dispatchEvent(new Event('change'));textarea.value=factDraft.text;textarea.dispatchEvent(new Event('input'));textarea.focus();feedback().textContent='Draft inserted. Check the facts and wording before sending; nothing was sent.';};
 async function perform(body,after){if(busy)return;busy=true;panel.querySelectorAll('button').forEach(b=>b.disabled=true);try{const result=await api(body);if(after)after(result);else{pending=null;show(await api());panel.querySelector('.support-feedback').textContent=body.action==='internal'?'Private note saved.':body.action==='contact'?'Email saved.':body.action==='revoke'?'Customer access links revoked.':'Saved to the customer conversation. Email activity shows notification status.';}}catch(e){if(e.rejected)pending=null;feedback().textContent=e.message+(pending?' Retry will send the original message once.':'');panel.querySelector('#support-text').disabled=!!pending;panel.querySelector('#support-kind').disabled=!!pending;}finally{busy=false;panel.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 panel.querySelector('#support-reply').onsubmit=e=>{e.preventDefault();pending||={action:panel.querySelector('#support-kind').value,text:panel.querySelector('#support-text').value,requestId:crypto.randomUUID()};perform(pending);};
 panel.querySelector('#support-kind').onchange=e=>{panel.querySelector('#support-reply button').textContent=e.target.value==='internal'?'Save private note':e.target.value==='request'?'Request information':'Send to customer';};
 panel.querySelector('#support-refresh').onclick=async()=>{const draft=panel.querySelector('#support-text').value;const kind=panel.querySelector('#support-kind').value;try{show(await api());panel.querySelector('#support-text').value=draft;panel.querySelector('#support-kind').value=kind;panel.querySelector('#support-kind').dispatchEvent(new Event('change'));panel.querySelector('#support-text').dispatchEvent(new Event('input'));}catch(e){feedback().textContent=e.message;}};
 panel.querySelector('#support-contact').onsubmit=e=>{e.preventDefault();perform({action:'contact',email:panel.querySelector('#support-email').value});};
 panel.querySelector('#support-link').onclick=()=>perform({action:'link'},r=>{const box=panel.querySelector('#support-link-result');box.textContent='Private link — share only with the verified purchaser: ';const a=document.createElement('a');a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=r.url;a.className='private-link';box.append(a);});
 panel.querySelector('#support-invite').onclick=()=>perform({action:'invite'},r=>feedback().textContent=r.message);
 panel.querySelector('#support-revoke').onclick=()=>perform({action:'revoke'});
 mountSupportPolish(panel,s,d);mountUpdatePromise(root,panel,s.id,d.nextUpdateAt,d.notifications);mountReminderPanel(root,d,()=>{});
 }
 panel.innerHTML='<p role="status">Loading customer conversation…</p>';api().then(d=>{if(panel.isConnected)show(d);}).catch(e=>{panel.textContent='Customer conversation unavailable. '+e.message;const b=document.createElement('button');b.className='button';b.textContent='Retry conversation';b.onclick=()=>api().then(show).catch(e=>panel.firstChild.textContent=e.message);panel.append(b);});
}
